const slug = $('Campaign Slug').first().json;
const funnel = $('Funnel Metrics').first().json;
const noClickRows = $('Opens Without Click').all().map(i => i.json);

const sent = Number(funnel.sent || 0);
const delivered = Number(funnel.delivered || 0);
const openedHuman = Number(funnel.opened_human || 0);
const clicked = Number(funnel.clicked || 0);
const replied = Number(funnel.replied || 0);
const complaints = Number(funnel.complaints || 0);
const enrolled = Number(funnel.enrolled || 0);
const stillInSequence = Number(funnel.still_in_sequence || 0);
const sequenceComplete = enrolled > 0 && stillInSequence === 0;

const deliveredRate = sent > 0 ? delivered / sent : 0;
const openRate = delivered > 0 ? openedHuman / delivered : 0;
const clickRateOfOpens = openedHuman > 0 ? clicked / openedHuman : 0;
const complaintRate = sent > 0 ? complaints / sent : 0;

let diagnosis = 'Insufficient data — wait for more sends.';
let recommendation = 'Continue monitoring.';

if (complaintRate > 0.001) {
  diagnosis = `Complaint-rate ${(complaintRate * 100).toFixed(2)}% > 0.1% — list or tone problem.`;
  recommendation = 'Stop (complaint-rate > 0.1%)';
} else if (sent > 0 && deliveredRate < 0.95) {
  diagnosis = `Delivered-rate ${(deliveredRate * 100).toFixed(1)}% < 95% — deliverability or list quality issue.`;
  recommendation = 'Iterate Subject';
} else if (delivered > 0 && openRate < 0.25) {
  diagnosis = `Open-rate (human) ${(openRate * 100).toFixed(1)}% < ~25% — subject or sender problem.`;
  recommendation = 'Iterate Subject';
} else if (openedHuman > 0 && clickRateOfOpens < 0.03) {
  diagnosis = `Opens ok (${openedHuman}), click-rate ${(clickRateOfOpens * 100).toFixed(1)}% of opens < ~3% — copy/CTA problem.`;
  recommendation = 'Iterate Copy';
} else if (clicked > 0 && replied === 0) {
  diagnosis = `Clicks ok (${clicked}) but no replies yet — offer or ICP mismatch.`;
  recommendation = 'Pivot Offer';
} else if (replied > 0) {
  diagnosis = `Replies received (${replied}) — sequence producing engagement.`;
  recommendation = 'Continue monitoring.';
}

let validationVerdict = 'INCOMPLETE';
let validationNotes = 'Sequence still running — wait for all 3 weekly touches or early reply/click signal.';
if (complaintRate > 0.001) {
  validationVerdict = 'FAIL';
  validationNotes = 'Stopped — complaint rate exceeded 0.1%.';
} else if (replied >= 1) {
  validationVerdict = 'PASS';
  validationNotes = `${replied} reply/replies — hard pass (early or after full sequence). Confirm replies are substantive.`;
} else if (clicked >= 3) {
  validationVerdict = 'PASS';
  validationNotes = `0 replies but ${clicked} human clicks — soft pass; proceed with caution.`;
} else if (sequenceComplete && replied === 0 && clicked < 3) {
  validationVerdict = 'FAIL';
  validationNotes = 'Full 3-touch sequence complete for all enrolled leads — 0 replies and <3 human clicks. Set status: validation-failed.';
} else if (enrolled === 0) {
  validationNotes = 'No leads enrolled yet.';
}

const noClickTable = noClickRows.length
  ? noClickRows.map(r => `| ${r.recipient} | ${r.opens} | ${r.clicks} | ${r.last_event} |`).join('\n')
  : '| — | — | — | — |';

const markdown = `# 05 — Campaign Diagnostics\n\n> Generated by n8n Workflow 5 on ${new Date().toISOString().slice(0, 10)}.\n> Opens are a **soft** signal (Apple MPP / scanners inflate them); clicks and\n> replies are **hard** signals.\n\n## Funnel\n| sent | delivered | opened_human | clicked | replied |\n|---|---|---|---|---|\n| ${sent} | ${delivered} | ${openedHuman} | ${clicked} | ${replied} |\n\n## Opens without click (per recipient)\n| recipient | opens | clicks | last_event |\n|---|---|---|---|\n${noClickTable}\n\n## Diagnosis\n${diagnosis}\n\n## Recommendation\n${recommendation}\n\n## Validation verdict (v2)\n- **Verdict:** ${validationVerdict}\n- **Positive replies:** ${replied} (need ≥1 for hard pass)\n- **Human clicks:** ${clicked} (need ≥3 for soft pass)\n- **Sends completed:** ${sent} (enrolled: ${enrolled}, in sequence: ${stillInSequence})\n- **Notes:** ${validationNotes}\n\n## KPI (legacy — not used in v2 validation)\n- **Discovery calls:** <n> / 30\n- **Preorders:** <n> / ≥1\n`;

return [{
  json: {
    campaign: slug.campaign,
    report_path: slug.report_path,
    diagnosis,
    recommendation,
    validation_verdict: validationVerdict,
    funnel: { sent, delivered, opened_human: openedHuman, clicked, replied },
  },
  binary: {
    data: {
      data: Buffer.from(markdown, 'utf8').toString('base64'),
      mimeType: 'text/markdown',
      fileName: '05-campaign-diagnostics.md',
    }
  }
}];
